#!/bin/bash
# queue11.sh STORY...: the same as queue10.sh with the stories 69 to 77, and the extraction cache cleared just before the HyperFrames render when
# no other HyperFrames render is running (it refuses to start under 1 GB free; queue10 cleared it by hand before the run). Previous comment of queue10:
# queue10.sh STORY...: the same as queue9.sh with the stories 57 and 58 (a queue script must not be edited while one of its runs is going: bash reads a script as it runs)
# re-render the given stories (3D layer -> project -> HyperFrames render) next to the main queue
cd /home/user/myownshit/absurd-shorts
SC=/tmp/claude-0/-home-user-myownshit/55de8c21-9e41-5895-8198-7b13ed3b7877/scratchpad/s7
declare -A NUM=([sable]=10 [lune]=11 [sapin]=12 [escargot]=13 [greve]=14 [colis]=15 [heure]=16 [police]=17 [burger]=18 [loto]=19 [independance]=20 [velo]=21 [caillou]=22 [rdv]=23 [balance]=24 [sosie]=25 [teletravail]=26 [gps]=27 [aspirateur]=28 [serrurier]=29 [armoire]=30 [parapluie]=31 [attente]=32 [wifi]=33 [canicule]=34 [ver]=35 [chaussettes]=36 [trou]=37 [eternuement]=38 [porte]=39 [interrupteur]=40 [elan]=41 [ombre]=42 [cravate]=43 [statue]=44 [fourriere]=45 [radar]=46 [aimant]=47 [codebarre]=48 [photocopie]=49 [hoquet]=50 [gomme]=51 [boomerang]=52 [torticolis]=53 [valise]=54 [ventouse]=55 [bosse]=56 [tournante]=57 [baillement]=58 [grimace]=59 [echo]=60 [ressort]=61 [soleil]=62 [cafe]=63 [langue]=64 [poisson]=65 [feu]=66 [moustache]=67 [champagne]=68 [lunettes]=69 [tondeuse]=70 [robinet]=71 [bus]=72 [conseiller]=73 [pull]=74 [parcmetre]=75 [ascenseur]=76 [centime]=77 [bocal]=78 [table]=80 [guepe]=81 [flaque]=82 [barbecue]=83 [rambarde]=84 [place]=85 [feuille]=86 [chat]=87 [cheveu]=88 [tonnerre]=89 [rayon]=90 [pizza]=91 [stylo]=92 [tache]=93 [numero]=94 [distributeur]=95 [chifoumi]=96 [pneu]=97 [grincement]=98 [fuite]=99 [pelle]=100 [regime]=101 [tartine]=102 [pardon]=103 [poule]=104 [mot]=105 [composteur]=106 [notice]=107 [sardine]=108 [sel]=109 [bulletin]=110 [moutons]=111 [spaghetti]=112 [minuterie]=113)
declare -A TITLE=([sable]="Le sable" [lune]="La Lune" [sapin]="Le sapin" [escargot]="L'escargot" [greve]="La grève des nuages" [colis]="L'avis de passage" [heure]="Le changement d'heure" [police]="La police contre la police" [burger]="Le burger vegan" [loto]="Le loto" [independance]="L'indépendance" [velo]="Le vélo" [caillou]="Le caillou" [rdv]="Le rendez-vous" [sosie]="Le sosie" [balance]="La balance" [teletravail]="Le télétravail" [gps]="Le GPS" [aspirateur]="L'aspirateur" [serrurier]="Le serrurier" [armoire]="L'armoire" [parapluie]="Le parapluie" [attente]="La file d'attente" [wifi]="Le wifi" [canicule]="La canicule" [ver]="Le ver de terre" [chaussettes]="Les chaussettes" [trou]="Le trou" [eternuement]="L'éternuement" [porte]="La porte" [interrupteur]="L'interrupteur" [elan]="L'élan" [ombre]="L'ombre" [cravate]="La cravate" [statue]="La statue" [fourriere]="La fourrière" [radar]="Le radar" [aimant]="L'aimant" [codebarre]="Le code-barres" [photocopie]="La photocopieuse" [hoquet]="Le hoquet" [gomme]="La gomme à mâcher" [boomerang]="Le boomerang" [torticolis]="Le torticolis" [valise]="La valise" [ventouse]="La ventouse" [bosse]="La bosse" [tournante]="La porte tournante" [baillement]="Le bâillement" [grimace]="La grimace" [echo]="L'écho" [ressort]="Le ressort" [soleil]="Le coup de soleil" [cafe]="Le café" [langue]="La langue" [poisson]="Le poisson rouge" [feu]="Le feu rouge" [moustache]="La moustache" [champagne]="Le champagne" [lunettes]="Les lunettes" [tondeuse]="La tondeuse" [robinet]="Le robinet" [bus]="Le bus" [conseiller]="Le service client" [pull]="Le pull" [parcmetre]="Le parcmètre" [ascenseur]="L'ascenseur" [centime]="Le centime" [bocal]="Le bocal" [table]="La table basse" [guepe]="La guêpe" [flaque]="La flaque" [barbecue]="Le barbecue" [rambarde]="La rambarde" [place]="La place" [feuille]="La feuille" [chat]="Le chat" [cheveu]="Le cheveu" [tonnerre]="Le tonnerre" [rayon]="Le rayon" [pizza]="La pizza" [stylo]="Le stylo" [tache]="La tache" [numero]="Le faux numéro" [distributeur]="Le distributeur" [chifoumi]="Le chifoumi" [pneu]="Le pneu" [grincement]="Le grincement" [fuite]="La fuite" [pelle]="La pelle" [regime]="Le régime" [tartine]="La tartine" [pardon]="Le pardon" [poule]="La poule" [mot]="Le mot" [composteur]="Le composteur" [notice]="La notice" [sardine]="La sardine" [sel]="Le sel" [bulletin]="Le bulletin" [moutons]="Les moutons" [spaghetti]="Le spaghetti" [minuterie]="La minuterie")
for S in "$@"; do
  mkdir -p $SC/$S
  cp scripts-fr/story_$S.json scripts-fr/story_${S}_render.json
  node render/render3.mjs scripts-fr/story_${S}_render.json --timed --w 1080 --h 1920 --workers 3 --out out/story_${S}_3d.mp4 > $SC/$S/render2.log 2>&1 || { echo "$S v2 3D FAILED" >> $SC/queue.log; continue; }
  P=/home/user/myownshit/hyperframes/${NUM[$S]}-$S
  python3 stories7/make_project.py $S $P "${TITLE[$S]}" >> $SC/queue2.log 2>&1 || { echo "$S v2 PROJECT FAILED" >> $SC/queue.log; continue; }
  cp out/story_${S}_3d.mp4 $P/assets/layer3d.mp4
  pgrep -f 'hyperframes@0.9.13 render' > /dev/null || rm -rf /tmp/hyperframes-extract-cache-0/hfcache-*   # (queue11) disk for the extraction, unless another render is using the cache
  (cd $P && export NODE_USE_ENV_PROXY=1 NODE_EXTRA_CA_CERTS=/root/.ccr/ca-bundle.crt && npx --yes hyperframes@0.9.13 check --json > $SC/$S/check.json 2>/dev/null; mkdir -p renders && npx --yes hyperframes@0.9.13 render -o renders/$S.mp4 --fps 30 > $SC/$S/hf2.log 2>&1) && echo "$S v2 DONE $P/renders/$S.mp4" >> $SC/queue.log || echo "$S v2 HF FAILED" >> $SC/queue.log
done
echo "QUEUE2 FINISHED" >> $SC/queue.log
